(() => {
  const $ = id => document.getElementById(id);
  const esc = text => String(text ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const style = document.createElement('link'); style.rel='stylesheet'; style.href='./platform.css'; document.head.append(style);
  const nav = document.querySelector('#view-tabs');
  nav.querySelector('[data-view-target="special"] small').textContent='符箓图鉴 · 紫微';
  nav.querySelector('[data-view-target="folk"] span').textContent='堪舆';
  nav.querySelector('[data-view-target="folk"] small').textContent='全景 · 勘察 · 档案';
  const toolCard=document.querySelector('.c-tools'); toolCard.querySelector('em').textContent='紫微命盘、照片初筛、梅花、六爻与干支';toolCard.querySelector('b').textContent='5 工具 →';
  const folkCard=document.querySelector('.c-folk');folkCard.querySelector('strong').textContent='堪舆工作台';folkCard.querySelector('em').textContent='阳宅、阴宅、商铺、村落与场地勘察';folkCard.querySelector('b').textContent='6 场景 · 可导出 →';
  const diagrams=[
    {name:'符头 · 起首结构',tag:'形制入门',label:'起',path:'M55 90 L140 65 L225 90 M80 106 H200 M95 120 H185 M140 120 V180 M105 158 L140 185 L177 155',body:'观察上部是否有文字、图形或复合笔画，以及它与主体之间的衔接。不同文献与传承的起首结构并不相同。',read:'先记录纸张、颜色、方向与起笔位置，再对照整页题名和上下文。仅凭一枚图形不能确定法派或年代。',exercise:'描出图形的外轮廓，标出文字与非文字笔画，分别记录可读和不可读部分。'},
    {name:'符身 · 复合笔画',tag:'结构观察',label:'文',path:'M140 85 V310 M75 120 L205 160 M80 190 L200 165 M75 235 L208 260 M100 285 L175 230 M110 130 Q215 210 112 270',body:'主体可能结合文字、篆形、线条与重叠图案。阅读时应保留原图的空间关系，不能把所有线条强行拆成汉字。',read:'分别观察纵向主轴、横向交叠、围合区域与留白；“符头、符身、符脚”是便于学习的描述方式，并非统一格式。',exercise:'用三种颜色分别标注轴线、围合与交叉，写下哪些部分无法释读。'},
    {name:'符脚 · 收束形式',tag:'形制入门',label:'收',path:'M140 80 V225 M90 140 H190 M100 190 H180 M140 225 L80 285 L115 270 L100 315 M140 225 L205 285 L168 270 L185 315 M140 230 V330',body:'下部收束可以表现为文字、分叉笔画或其他图形。它与整体布局共同构成视觉秩序。',read:'先比较同一文献中的多幅图，再讨论差异；不要把单一收笔方式解释为普遍有效的身份标记。',exercise:'比较三种收笔方向，记录它们如何改变画面重心。'},
    {name:'篆形 · 文字与图像',tag:'书写研究',label:'篆',path:'M82 95 H198 V285 H82 Z M110 95 V250 H170 V125 H140 V285 M82 155 H110 M170 205 H198',body:'道教文献中存在多样的特殊文字与图像表达。“云篆”等术语需结合具体经典和篇章理解，不能直接等同于现代字体。',read:'这一幅为几何化文字结构练习图，不是对某部经典中云篆的释文或复原。',exercise:'建立图形索引：编号、页码、图版、可辨文字、释读来源与疑问。'},
    {name:'印式 · 方框布局',tag:'章印观察',label:'印',path:'M65 85 H215 V290 H65 Z M78 98 H202 V277 H78 Z M95 118 H185 V145 H120 V177 H180 V245 H95 V215 H150 V190 H95 Z',body:'章印与符图在页面中可能相邻出现，但用途与文献身份需分别记录。方框图形本身并不能证明它是历史法印。',read:'此图为原创方框布局示意。实物研究还应记录印面尺寸、边款、材质与收藏来源。',exercise:'制作一张印面观察卡：正反方向、边框层数、文字布局与磨损。'},
    {name:'符箓文献 · 整页阅读',tag:'文献方法',label:'册',path:'M65 85 H215 V305 H65 Z M88 112 H192 M88 133 H192 M88 154 H128 M151 160 V245 M130 183 H182 M130 220 L180 200 M88 270 H192',body:'“符”与“箓”不能简单混作一张图。研究箓牒、章奏与符图，应同时保留题名、文字、编次与仪式语境。',read:'先核对书名、版本、卷次、页码、馆藏或影像链接。本站图鉴是结构学习材料，不替代原典图版。',exercise:'给每个资料条目填写来源卡，来源不明时明确写“待核验”，不推测作者与功效。'}
  ];
  function svg(d,i){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 280 400" role="img" aria-label="${d.name}原创结构示意"><rect width="280" height="400" fill="#dbc28b"/><rect x="18" y="18" width="244" height="364" fill="none" stroke="#87382a"/><text x="140" y="53" text-anchor="middle" fill="#87382a" font-size="17">${d.label} · 结构示意 ${i+1}</text><path d="${d.path}" fill="none" stroke="#87382a" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><text x="140" y="365" text-anchor="middle" fill="#87382a" font-size="11">玄道易术 · 原创研习图</text></svg>`}
  const gallery=document.createElement('section');gallery.className='platform-section';gallery.id='talisman-atlas';gallery.dataset.viewSection='special';
  gallery.innerHTML=`<div class="platform-title"><p class="eyebrow">图像 · 解释 · 研习</p><h2>符箓结构图鉴</h2><p>六组可放大、可下载的原创学习图。每图附结构说明、阅读方法和一项练习；图形为教学设计，未声称来自历史法本。</p></div><div class="atlas-grid">${diagrams.map((d,i)=>`<button class="atlas-card" data-diagram="${i}">${svg(d,i)}<span>${d.tag}</span><h3>${d.name}</h3><p>${d.body}</p><b>看大图与解释 ↗</b></button>`).join('')}</div><div class="reference-strip"><h3>资料与出处怎么查</h3><p>推荐从《正统道藏》《万历续道藏》与《道法会元》的版本目录入手。这里只提供检索线索，尚未核对具体卷页的图版不会标作原典摹本。收录实物时，应一并记录馆藏、授权、版本和页码。</p><a href="https://ctext.org/library.pl?if=gb" target="_blank" rel="noopener">中国哲学书电子化计划 · 图书馆 ↗</a></div>`;
  document.querySelector('#special').after(gallery);
  const dialog=document.createElement('dialog');dialog.className='atlas-dialog';document.body.append(dialog);
  gallery.addEventListener('click',e=>{const btn=e.target.closest('[data-diagram]');if(!btn)return;const i=Number(btn.dataset.diagram),d=diagrams[i];dialog.innerHTML=`<form method="dialog"><button class="dialog-close" aria-label="关闭">×</button></form><div class="atlas-detail">${svg(d,i)}<div><p class="eyebrow">原创结构示意</p><h2>${d.name}</h2><p>${d.body}</p><h3>如何阅读</h3><p>${d.read}</p><h3>照着做一次</h3><p>${d.exercise}</p><button class="button ink" id="download-diagram">下载 SVG 图</button></div></div>`;dialog.querySelector('#download-diagram').onclick=()=>download(`${d.name}.svg`,svg(d,i),'image/svg+xml');dialog.showModal();});
  const scenarios=[
    {name:'阳宅住宅',symbol:'宅',focus:'居住舒适与日常动线',checks:['入口与室内主要通道','客厅、床位与书桌使用习惯','自然采光与夜间照明','通风、潮湿与异味来源','厨房火源与卫生间排水','噪声、隐私与邻里影响'],terms:'门、堂、房、灶：先记录空间和使用方式，再讨论传统格局名称。',example:'两居室客厅西晒，午后屏幕反光。先拍早晚对照图，记录遮阳条件，再考虑可调窗帘与座位角度。'},
    {name:'阴宅墓园',symbol:'陵',focus:'山水形势、纪念空间与维护',checks:['山坡走势与周边地势','汇水路径、积水与冲刷痕迹','墓体、挡墙和台阶现状','祭扫通道与老人通行条件','植被根系与日常维护','墓园管理、边界与现场许可'],terms:'龙、穴、砂、水、向：作为传统观察词汇分别记录；不能据此承诺后代祸福。',example:'坡地墓区雨后有泥沙堆积。记录上坡汇水和排水沟现状，拍摄同角度复查照片，将维护问题交墓园管理方处理。'},
    {name:'商铺办公',symbol:'业',focus:'可达性、经营动线与工作环境',checks:['街道视线与入口可识别性','顾客与员工动线','展示、收银与等候区域','工位照明与屏幕眩光','货物、线缆与通道占用','消防疏散与出入口现状'],terms:'门面、明堂与流线：区分传统比喻和可测量的经营条件。',example:'临街店入口被陈列架遮住。对照行人视角拍照，记录拥堵时段，先调整陈列与标识，不将营业额归因于方位。'},
    {name:'村落聚落',symbol:'村',focus:'整体地形、水系与公共空间',checks:['山脊、谷地与聚落轮廓','河流、沟渠和排水网络','街巷联系与公共活动节点','古树、水口与地方记忆','老建筑现状与维护需求','道路、公共服务与应急通达'],terms:'水口、明堂、靠山：结合地方历史、地形和水文资料记录，保留居民口述的来源。',example:'老村入口水渠与古树相邻。分别绘制现状草图、记录居民口述与雨后排水情况，避免把口述传说写成工程结论。'},
    {name:'园林庭院',symbol:'园',focus:'视线、植物与季节变化',checks:['入口至主要活动区路径','地面坡度与排水位置','树木生长空间与遮阴','池水、台阶与照明','坐憩点视野与私密性','落叶、积水与季节维护'],terms:'藏、露、借景与曲直：可用于解释空间体验，应结合实际使用者需求。',example:'庭院小径雨后积水，树荫区湿滑。标注积水边界与持续时间，记录地面材料，再请专业人员评估排水和防滑处理。'},
    {name:'山水场地',symbol:'山',focus:'地形、水文与场地初查',checks:['等高线、坡向与坡度来源','天然沟谷和洪水痕迹','岩土、裂隙与边坡现状','道路、能源与水源条件','周边用地与生态现状','需专业勘察的未知项'],terms:'形势与理气：分别记录地形观察、方位数据与采用的传统解释，不混为测绘结论。',example:'山脚空地邻近干沟。晴天照片不足以判断洪水风险，应记录沟谷走向、历史水痕与资料缺口，再委托相应专业调查。'}
  ];
  const workspace=document.createElement('section');workspace.id='survey-workbench';workspace.dataset.viewSection='folk';workspace.className='platform-section survey-section';
  workspace.innerHTML=`<div class="platform-title"><p class="eyebrow">堪舆全景 · 实地记录</p><h2>从现场到一份完整报告</h2><p>选择场景，参考案例，逐项观察并保存。所有记录留在当前设备；报告可复制、下载或打印。</p></div><div class="survey-layout"><nav class="scenario-nav" aria-label="勘察场景">${scenarios.map((s,i)=>`<button data-scenario="${i}" class="${i===0?'active':''}"><b>${s.symbol}</b><span>${s.name}<small>${s.focus}</small></span></button>`).join('')}</nav><div class="survey-body"><div id="scenario-overview"></div><form id="survey-form"><div class="survey-fields"><label>项目名称<input name="title" required placeholder="例如：城西老宅现场观察"></label><label>观察日期<input name="date" type="date"></label><label>方位 / 测量方式<input name="direction" placeholder="例如：手机罗盘实测，需复核"></label><label>天气 / 时段<input name="weather" placeholder="例如：晴，上午 10 时"></label></div><div id="survey-checks"></div><label>现场事实<textarea name="facts" placeholder="记录能看到、测到的事实，注明照片编号"></textarea></label><label>传统术语与解释<textarea name="interpretation" placeholder="写明采用的术语、文献线索与不确定之处"></textarea></label><label>处理顺序与待核验事项<textarea name="actions" placeholder="按优先级记录：事项 / 负责方 / 复查日期"></textarea></label><div class="survey-actions"><button type="submit" class="button ink">保存到本机</button><button type="button" id="survey-example" class="button ghost">填入示范作业</button><button type="button" id="survey-report" class="button cinnabar">生成报告</button></div><p id="survey-status" role="status"></p></form></div></div><div class="report-panel" id="survey-output" hidden><h3>勘察报告预览</h3><textarea id="survey-report-text" aria-label="报告全文"></textarea><div class="survey-actions"><button id="report-copy" class="button ink">复制报告</button><button id="report-download" class="button ghost">下载文本</button><button id="report-print" class="button ghost">打印报告</button></div></div><div class="platform-roadmap"><h3>完整平台的使用地图</h3><div><span>① 学习：体系、图鉴、原典</span><span>② 实践：个人排盘、照片初筛</span><span>③ 勘察：六类场景与示范</span><span>④ 交付：本机档案与报告</span></div><p>当前已实现以上浏览器端流程。团队协作、跨设备同步、历史实物图库与专业图像模型尚未接入；后续需要独立账号、数据服务和可核验资料。</p></div>`;
  document.querySelector('#folk-notes').before(workspace);
  let selected=0;const form=$('survey-form');const storageKey=i=>`xuandao-survey-v1-${i}`;
  function collect(){const v=Object.fromEntries(new FormData(form));v.checks=[...form.querySelectorAll('[data-check]')].map(e=>({name:e.dataset.check,value:e.value}));return v;}
  function populate(v){for(const name of ['title','date','direction','weather','facts','interpretation','actions'])form.elements[name].value=v[name]||'';(v.checks||[]).forEach((c,i)=>{const el=form.querySelectorAll('[data-check]')[i];if(el)el.value=c.value;});}
  function switchScenario(i){selected=i;const s=scenarios[i];workspace.querySelectorAll('[data-scenario]').forEach(b=>b.classList.toggle('active',Number(b.dataset.scenario)===i));$('scenario-overview').innerHTML=`<p class="eyebrow">${s.focus}</p><h3>${s.name}勘察模板</h3><p>${s.terms}</p><details><summary>参考一份示范作业</summary><p>${s.example}</p><p>交付结构：基本信息 → 现场事实 → 传统解释 → 待核验问题 → 行动与复查。</p></details>`;$('survey-checks').innerHTML=`<h4>六项现场复核</h4>${s.checks.map((c,j)=>`<label class="survey-check"><span>${String(j+1).padStart(2,'0')} · ${c}</span><select data-check="${c}" aria-label="${c}"><option value="未观察">未观察</option><option value="已观察 · 暂未发现问题">已观察 · 暂未发现问题</option><option value="需复核">需复核</option><option value="需处理">需处理</option><option value="不适用">不适用</option></select></label>`).join('')}`;form.reset();$('survey-output').hidden=true;$('survey-status').textContent='';try{const saved=localStorage.getItem(storageKey(i));if(saved){populate(JSON.parse(saved));$('survey-status').textContent='已载入此场景的本机记录。';}else form.elements.date.value=new Date().toLocaleDateString('sv-SE');}catch{ $('survey-status').textContent='本机存储不可用，仍可生成并下载报告。';}}
  workspace.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{try{sessionStorage.setItem(storageKey(selected),JSON.stringify(collect()));}catch{}switchScenario(Number(b.dataset.scenario));try{const draft=sessionStorage.getItem(storageKey(selected));if(draft)populate(JSON.parse(draft));}catch{}});
  form.onsubmit=e=>{e.preventDefault();try{localStorage.setItem(storageKey(selected),JSON.stringify(collect()));$('survey-status').textContent='已保存到本机浏览器；可继续生成报告。';}catch{$('survey-status').textContent='保存失败，请生成报告后下载备份。';}};
  $('survey-example').onclick=()=>{if(form.elements.facts.value&&!confirm('用示范内容替换当前表单？已保存的本机记录不会被覆盖。'))return;const s=scenarios[selected];populate({title:s.name+' · 示范作业（虚构教学案例）',date:new Date().toLocaleDateString('sv-SE'),direction:'待现场测量，示范不设定方位',weather:'示例：雨后复查',facts:s.example,interpretation:s.terms,actions:'1. 补充同角度照片与现场尺寸。\n2. 将观察、传统解释与未知项分开记录。\n3. 如涉及工程维护，交由相应专业人员复核。\n4. 处理后按相同位置复拍并记录日期。'});$('survey-status').textContent='示范已填入，可修改后另存。';};
  function report(){const v=collect(),s=scenarios[selected];return `玄道易术 · ${s.name}勘察记录\n${v.title||'未命名项目'}\n日期：${v.date||'未填写'}\n方位 / 测量方式：${v.direction||'未填写'}\n天气 / 时段：${v.weather||'未填写'}\n\n一、现场复核\n${v.checks.map(c=>`${c.name}：${c.value}`).join('\n')}\n\n二、现场事实\n${v.facts||'待填写'}\n\n三、传统术语与解释\n${v.interpretation||'待填写'}\n\n四、处理顺序与待核验\n${v.actions||'待填写'}\n\n记录为观察与文化研习材料；未观察项与待核验项不构成现场结论。`;}
  $('survey-report').onclick=()=>{$('survey-report-text').value=report();$('survey-output').hidden=false;$('survey-output').scrollIntoView({behavior:'smooth'});};
  $('report-copy').onclick=async()=>{try{await navigator.clipboard.writeText($('survey-report-text').value);$('report-copy').textContent='已复制';}catch{$('survey-report-text').select();$('report-copy').textContent='请长按或按 Ctrl+C 复制';}};
  $('report-download').onclick=()=>download('堪舆勘察报告.txt',$('survey-report-text').value,'text/plain;charset=utf-8');
  $('report-print').onclick=()=>{const w=window.open('','_blank');if(!w)return;w.document.write(`<html><head><title>勘察报告</title><style>body{font:15px/1.9 serif;padding:40px}pre{white-space:pre-wrap}</style></head><body><pre>${esc($('survey-report-text').value)}</pre></body></html>`);w.document.close();w.print();};
  function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  switchScenario(0);
})();
